<?php
require_once __DIR__ . '/../config/database.php';
function getUsers(string $search=''): array {global $pdo;$s=$pdo->prepare("SELECT id,name,email,role,password FROM users WHERE (:q='' OR name LIKE :n OR email LIKE :e) ORDER BY id DESC");$like="%{$search}%";$s->execute(['q'=>$search,'n'=>$like,'e'=>$like]);return $s->fetchAll();}
function getUserById(int $id): ?array {global $pdo;$s=$pdo->prepare("SELECT id,name,email,role,password FROM users WHERE id=?");$s->execute([$id]);return $s->fetch()?:null;}
function getUserByEmail(string $email): ?array {global $pdo;$s=$pdo->prepare("SELECT id,name,email,role,password FROM users WHERE email=?");$s->execute([$email]);return $s->fetch()?:null;}
function getProfile(int $userId): array {global $pdo;$s=$pdo->prepare("SELECT user_id,phone,address,bio FROM profiles WHERE user_id=?");$s->execute([$userId]);return $s->fetch()?:['user_id'=>$userId,'phone'=>'','address'=>'','bio'=>''];}
function createUser(array $d): int {global $pdo;$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)");$s->execute([$d['name'],$d['email'],$d['password'],$d['role']]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO profiles(user_id) VALUES(?)")->execute([$id]);return $id;}
function updateUser(array $d,int $id): void {global $pdo;$s=$pdo->prepare("UPDATE users SET name=?,email=?,role=? WHERE id=?");$s->execute([$d['name'],$d['email'],$d['role'],$id]);}
function deleteUser(int $id): void {global $pdo;$s=$pdo->prepare("DELETE FROM users WHERE id=?");$s->execute([$id]);}
function updateProfile(array $d,int $id): void {global $pdo;$pdo->beginTransaction();try{$pdo->prepare("UPDATE users SET name=?,email=? WHERE id=?")->execute([$d['name'],$d['email'],$id]);$pdo->prepare("INSERT INTO profiles(user_id,phone,address,bio) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE phone=VALUES(phone),address=VALUES(address),bio=VALUES(bio)")->execute([$id,$d['phone'],$d['address'],$d['bio']]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}
